import * as SecureStore from 'expo-secure-store';

export async function salvarSessao(s: Sessao) {
  await SecureStore.setItemAsync('hakari_token', s.token, { keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY });
  banco.runSync(
    `INSERT INTO sessao (id, expira_em, usuario_id, nome, perfil) VALUES (1, ?, ?, ?, ?)
     ON CONFLICT(id) DO UPDATE SET expira_em = excluded.expira_em,
       usuario_id = excluded.usuario_id, nome = excluded.nome, perfil = excluded.perfil`,
    [s.expiraEm, s.usuario.id, s.usuario.nome, s.usuario.perfil],
  );
}

